{
  "name": "TEMPer USB温度传感器",
  "name_en": "TEMPer USB Temperature Sensor",
  "manufacturer": "",
  "description": "一种通过 USB 连接的温度传感器设备，用于实验中采集环境温度或样品附近温度。根据型号不同，可支持 1 到 2 个传感器通道，部分型号还可读取湿度数据，并可应用校准比例与偏移。",
  "description_en": "A USB-connected temperature sensing device used in laboratory setups to measure ambient temperature or temperature near a sample. Depending on the model, it may support 1 to 2 sensor channels, and some variants can also report humidity and apply calibration scale and offset.",
  "actions": [
    {
      "action_name": "auto-set_calibration_data",
      "description": "根据配置设置校准比例和偏移。",
      "description_en": "Set calibration scale and offset from configuration."
    },
    {
      "action_name": "auto-lookup_offset",
      "description": "查找指定传感器的温度偏移量。",
      "description_en": "Look up the temperature offset for a specified sensor."
    },
    {
      "action_name": "auto-lookup_humidity_offset",
      "description": "查找指定传感器的湿度偏移量。",
      "description_en": "Look up the humidity offset for a specified sensor."
    },
    {
      "action_name": "auto-lookup_sensor_count",
      "description": "根据产品名称查找设备的传感器数量。",
      "description_en": "Look up the number of sensors on the device based on the product name."
    },
    {
      "action_name": "auto-set_sensor_count",
      "description": "设置传感器数量。",
      "description_en": "Set the number of sensors."
    },
    {
      "action_name": "auto-close",
      "description": "关闭设备连接；此设备通常无需额外清理。",
      "description_en": "Close the device connection; this device typically requires no additional cleanup."
    }
  ],
  "tag_hints": [
    "USB temperature sensing",
    "humidity sensing",
    "multi-probe thermometer",
    "environment monitoring",
    "sensor calibration",
    "USB HID sensor"
  ]
}

